INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem booleschen Datentyp?', 2, '[{"text": "Datentyp für logische Werte", "correct": true, "because": "true und false"}, {"text": "Datentyp für Zahlen", "correct": false, "because": "Andere Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem booleschen Datentyp?', 3, '[{"text": "Logische Zustände speichern", "correct": true, "because": "Wahrheitswerte"}, {"text": "Speicherplatz sparen", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte kann ein boolescher Datentyp annehmen?', 5, '[{"text": "true", "correct": true, "because": "Wahr"}, {"text": "false", "correct": true, "because": "Falsch"}, {"text": "null", "correct": false, "because": "Nicht standardmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein boolescher Datentyp hat zwei Zustände. b) Er wird in SQL als INTEGER gespeichert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SQL hat BOOLEAN"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim booleschen Datentyp?', 4, '[{"text": "Logische Werte", "correct": false, "because": "Kern des Typs"}, {"text": "Verwendung in Bedingungen", "correct": false, "because": "Hauptanwendung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein boolescher Datentyp in SQL true und false unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "SQL-Standard"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Deklaration nutzt einen booleschen Datentyp?', 3, '[{"text": "BOOLEAN", "correct": true, "because": "Logischer Typ"}, {"text": "INTEGER", "correct": false, "because": "Numerisch"}, {"text": "VARCHAR", "correct": false, "because": "Text"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Arbeit mit einem booleschen Datentyp?', 5, '[{"text": "Logische Operationen", "correct": true, "because": "AND, OR"}, {"text": "Bedingte Abfragen", "correct": true, "because": "WHERE-Klausel"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein boolescher Datentyp wird für Flags genutzt. b) Er ist nur für große Datenmengen geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem booleschen Datentyp unwichtig?', 4, '[{"text": "Wahrheitswert", "correct": false, "because": "Kern"}, {"text": "Speichergröße", "correct": false, "because": "Relevant"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein boolescher Datentyp mehr als zwei Werte haben?', 2, '[{"text": "Nein", "correct": true, "because": "Nur true/false"}, {"text": "Ja", "correct": false, "because": "Binär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein boolescher Datentyp?', 4, '[{"text": "Einfache Logik", "correct": true, "because": "Klarheit"}, {"text": "Effiziente Bedingungen", "correct": true, "because": "Schnelle Abfragen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein boolescher Datentyp nur in SQL genutzt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Programmierung"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem booleschen Datentyp?', 3, '[{"text": "Logische Korrektheit", "correct": true, "because": "Wahrheitswerte"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein boolescher Datentyp wird in WHERE genutzt. b) Er speichert Zahlen von 0 bis 255.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nur true/false"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein boolescher Datentyp?', 5, '[{"text": "Begrenzte Werte", "correct": true, "because": "Nur zwei Zustände"}, {"text": "Eingeschränkte Flexibilität", "correct": true, "because": "Keine Zwischenwerte"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim booleschen Datentyp?', 3, '[{"text": "Logik implementieren", "correct": true, "because": "Bedingungen"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein boolescher Datentyp in einer Datenbank nullable sein?', 2, '[{"text": "Ja", "correct": true, "because": "NULL möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Abfrage nutzt einen booleschen Datentyp?', 4, '[{"text": "SELECT name FROM users WHERE is_active = true", "correct": true, "because": "Logische Bedingung"}, {"text": "INSERT INTO users VALUES (123)", "correct": false, "because": "Numerisch"}, {"text": "DELETE FROM users WHERE id = 1", "correct": false, "because": "Keine Logik"}]');
